export function renderView(s, r, p, ctx) {
  if (r.kind === 'dashboard') return dashboard(s, p, ctx);
  if (r.kind === 'entity') return entityView(s, r, p, ctx);
  if (['employees', 'new-hires'].includes(r.kind)) return employeesView(s, r, p, ctx);
  if (r.kind === 'add-employee') return card('Add Employee', formHtml(entities.employees.fields, { code: `ATI-${String(s.employees.length + 1).padStart(4, '0')}`, hireDate: today(), status: 'Active', employment: 'Full-time', salary: 24000 }, s, 'entity', 'data-entity="employees"', 'Add Employee'));
  if (['attendance', 'anomalies'].includes(r.kind)) return attendanceView(s, r, p, ctx);
  if (r.kind === 'absences') return absencesView(s, p, ctx);
  if (['face', 'nfc'].includes(r.kind)) return clockView(s, r, p);
  if (r.kind === 'cctv') return notice('Sample CCTV console. These are simulated camera feeds; no live camera or external connection is used.') + card('CCTV Monitoring', `<div class="cctv-grid">${['Main Entrance', 'Front Office', 'Restaurant', 'Employee Entrance'].map((name, i) => `<div class="cctv-tile"><span class="camera-label">CAM 0${i + 1} · ${name.toUpperCase()}</span><span class="camera-demo">● DEMO FEED</span>${icon('camera')}<strong>${name}</strong><small>Simulated monitoring</small><span class="camera-footer">${fmtDate(today())} · No live recording</span>${button('Simulate detection', 'cctv-detection', `data-camera="${name}"`, 'small secondary')}</div>`).join('')}</div>`);
  if (r.kind === 'schedule') return scheduleView(s, r, p, ctx);
  if (['schedules', 'no-shift', 'auto-balance'].includes(r.kind)) return shiftsList(s, r, p, ctx);
  if (r.kind === 'shift-requests') return shiftRequests(s, p, ctx);
  if (r.kind.startsWith('timesheet')) return timesheets(s, r, p, ctx);
  if (r.kind === 'leaves') return leaves(s, p, ctx);
  if (['leave-balance', 'employee-balances'].includes(r.kind)) return balances(s, r, p, ctx);
  if (['claims', 'claim-summary', 'claim-budgets'].includes(r.kind)) return claims(s, r, p, ctx);
  if (r.kind === 'assign-claim') return card('Assign Claims', claimForm(s));
  if (r.kind === 'users') return users(s, p, ctx);
  if (r.kind === 'create-user') return card('Create Employee Account', notice('New sample accounts appear in User Profiles. Only admin / admin can sign in to this demo.') + `<div style="margin-top:20px">${formHtml(entities.users.fields, { status: 'Active', role: 'Employee', timezone: 'Asia/Manila', locale: 'en-PH' }, s, 'entity', 'data-entity="users"', 'Create User')}</div>`);
  if (r.kind === 'notifications') return notifications(s, p, ctx);
  if (['settings', 'profile', 'preferences', 'pdf-settings', 'email-settings', 'discord-settings'].includes(r.kind)) return settingsView(s, r);
  if (['notification-management', 'email-outbox', 'sync', 'firebase', 'api'].includes(r.kind)) return integrationView(s, r, p, ctx);
  if (['health', 'audit', 'user-logs', 'modules'].includes(r.kind)) return healthView(s, r, p, ctx);
  return helpView(s, r);
}

